package com.garagedesk.controller; import com.garagedesk.entity.*; import com.garagedesk.service.JobCardService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.*; @RestController @RequestMapping("/api/job-cards") public class JobCardController{final JobCardService s;public JobCardController(JobCardService s){this.s=s;}@GetMapping public List<JobCard> all(){return s.all();}@PostMapping @ResponseStatus(HttpStatus.CREATED)public JobCard create(@RequestBody Req r){return s.create(r.vehicleId(),r.mechanicId(),r.bayId(),r.requestedServices(),r.customerComplaint(),r.workDescription(),r.scheduledStart(),r.scheduledEnd());}@PatchMapping("/{id}/status")public JobCard status(@PathVariable Long id,@RequestBody Map<String,String> b){return s.status(id,JobStatus.valueOf(b.get("status").toUpperCase()));}record Req(Long vehicleId,Long mechanicId,Long bayId,String requestedServices,String customerComplaint,String workDescription,LocalDateTime scheduledStart,LocalDateTime scheduledEnd){}}
